public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(SalesTable, AIBBookTable):
            this.AIBUpdateBookSalesLine();
            break;
    }
}

public void AIBUpdateBookSalesLine()
{
    SalesLine SalesLine;

    while select forupdate salesLine
                where salesLine.SalesId == this.SalesId
    {
        salesLine.AIBBookTable = this.AIBBookTable;
        if(salesLine.validateWrite())
        {
            salesLine.update();
        }
        ttscommit;

    }

    this.AIBResearchIfNeeded();
}

public void AIBResearchIfNeeded()
{
    FormDataSource formDataSource = FormDataUtil::getFormDataSource(this);

    if(formDataSource)
    {
        formDataSource.research(true);
    }

}

public Common AIBFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(AIBBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.AIBGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(AIBBookTable, Author));

    return refTableLookup.performFormLookup();
}
